Method.Source:
/// <summary>
/// designed from ava
/// </summary>
/// <param name = "_bom">_bom</param>
/// <param name = "_parentBOMCalcItem">_parentBOMCalcItem</param>
/// <param name = "_costingVersionId">_costingVersionId</param>
/// <param name = "_bomCalcFallBack">_bomCalcFallBack</param>
/// <param name = "_fallBackVersionId">_fallBackVersionId</param>
/// <param name = "_siteId">_siteId</param>
/// <param name = "_bomCalcExplosionMode">_bomCalcExplosionMode</param>
/// <returns>BOMCalcItemLine</returns>
static BOMCalcItemLine newBOMCalcItem(
    BOM                     _bom,
    BOMCalcItem             _parentBOMCalcItem,
    CostingVersionId        _costingVersionId,
    BOMCalcFallBack         _bomCalcFallBack,
    CostingVersionId        _fallBackVersionId,
    InventSiteId            _siteId,
    BOMCalcExplosionMode    _bomCalcExplosionMode
    )
{
    BOMCalcItemLine     bomCalcItemLine = next  newBOMCalcItem(_bom,_parentBOMCalcItem,_costingVersionId,_bomCalcFallBack,_fallBackVersionId,_siteId,_bomCalcExplosionMode);

    bomCalcItemLine.parmAVACostModelCombination(_parentBOMCalcItem.parmAVACostModelCombination());
    return bomCalcItemLine;
}

protected void initParameters()
{
    next initParameters();
    if (bom.bomType == BOMType::Vendor && bom.VendId != '')
    {
        vendAccount = bom.VendId;
    }
}
